mapper.select:
SELECT ID, BATCH_ID, STAFF_ID, BADGE, NAME, PARK_ID, DISPATCHER_PARK_ID, PERSON_ID, ISC_CARD_NO, LOCAL_CARD_NO, RESULT_CODE, RESULT_DESC, REASON, CREATE_TIME, UPDATE_TIME FROM SMT_ISC_CARD_IMPORT_DETAIL
AND PARK_ID IN
#{parkId}
AND BATCH_ID = #{query.batchId}
AND BADGE LIKE CONCAT(CONCAT('%',#{query.badge}),'%')
AND NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND ISC_CARD_NO LIKE CONCAT(CONCAT('%',#{query.iscCardNo}),'%')
AND RESULT_CODE = #{query.resultCode}
ORDER BY CREATE_TIME DESC, ID DESC
